SELECT id, tenant_id, project_id, previous_task_id, task_no, task_name, background, cutover_type_code, network_mode_code, schedule_time, task_origin_code, intake_source_type_code, source_system, source_business_no, business_event_id, current_stage_code, task_status_code, owner_user_id, customer_id, implementation_readiness_snapshot_id, implementation_readiness_snapshot_version, project_scope_version, manual_grade_code, current_assessment_id, legacy_task_id, legacy_cutover_type_raw, legacy_network_mode_raw, legacy_status_value, legacy_source_version, legacy_mapping_version, version, creator, create_time, updater, update_time, deleted, configuration_revision_id, configuration_code, configuration_revision_no, project_version, project_code, project_name, customer_code, customer_name, department_id, department_code, department_name, customer_fact_status_code, service_level_revision_id, service_level_code, customer_fact_version, service_level_effective_start_time, service_level_effective_end_time, readiness_decision_code
FROM cut_task
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.taskId}
  AND deleted = b'0'
FOR UPDATE

SELECT COALESCE(MAX(sequence_no), 0)
FROM cut_task_stage_history
WHERE tenant_id = #{query.tenantId}
  AND task_id = #{query.taskId}

mapper.update:
UPDATE cut_task
SET task_status_code = 'ARCHIVED', version = version + 1, update_time = NOW(3)
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.taskId}
  AND version = #{query.expectedVersion}
  AND task_origin_code = 'NEW_PLATFORM'
  AND current_stage_code = 'P6'
  AND task_status_code = 'CLOSURE_IN_PROGRESS'
  AND deleted = b'0'
